      END_STATE();
    case 283:
      ACCEPT_TOKEN(anon_sym_RPAREN);
      END_STATE();
    case 284:
      ACCEPT_TOKEN(sym_unsigned_integer);
      if (('0' <= lookahead && lookahead <= '9')) ADVANCE(284);
      END_STATE();
    case 285:
      ACCEPT_TOKEN(aux_sym_simple_type_definition_token1);
      END_STATE();
    case 286:
      ACCEPT_TOKEN(aux_sym_simple_type_definition_token2);
      END_STATE();
    case 287:
